// Central, non-secret firmware configuration. Secrets (Wi-Fi password,
// device token, backend URL) live in secrets.h, which is git-ignored and is
// generated by scripts/configure_device.sh.
#pragma once

#define FIRMWARE_VERSION        "2.0.0-dev.1"

// ---- Audio ------------------------------------------------------------------
#define AUDIO_SAMPLE_RATE       16000   // shared by ES8311 (out) and ES7210 (in)
#define AUDIO_FRAME_MS          20
#define AUDIO_FRAME_SAMPLES     (AUDIO_SAMPLE_RATE * AUDIO_FRAME_MS / 1000)   // 320 mono
#define AUDIO_MAX_CAPTURE_MS    20000   // hard limit per utterance (PSRAM: 640 KB)
#define AUDIO_MIN_CAPTURE_MS    300     // shorter recordings are never uploaded
#define AUDIO_MIC_GAIN_DB       30.0f   // ES7210 PGA gain [VERIFY by mic self-test RMS]
#define AUDIO_DEFAULT_VOLUME    70      // 0-100 codec volume (dashboard overrides)
#define AUDIO_PLAYBACK_RING     (256 * 1024)   // ~8 s of 16 kHz mono, in PSRAM
#define AUDIO_PREFILL_BYTES     6400    // 200 ms buffered before playback starts
#define AUDIO_UNDERRUN_FAIL_MS  8000    // stream starved this long -> playback error

// ---- Interaction timing (protocol §3.4) --------------------------------------
#define BUTTON_POLL_MS          5
#define BUTTON_DEBOUNCE_MS      25
#define BUTTON_LONG_PRESS_MS    2000
#define PROCESSING_TIMEOUT_MS   12000
#define CONTINUATION_WINDOW_MS  6000
#define SESSION_EXPIRY_MS       (10 * 60 * 1000)
#define SILENCE_ENDPOINT_MS     1500
#define NO_SPEECH_TIMEOUT_MS    8000

// ---- Networking ----------------------------------------------------------------
#define CONFIG_POLL_MS          1000    // condition changes apply within ~1 s
#define CONFIG_POLL_TIMEOUT_MS  1500
#define BACKEND_FAILS_OFFLINE   2       // consecutive poll failures -> OFFLINE (<5 s)
#define TURN_HTTP_TIMEOUT_MS    15000
#define WIFI_BACKOFF_MIN_MS     1000
#define WIFI_BACKOFF_MAX_MS     30000
#define MAX_TURN_WORKERS        2       // bounded concurrent turn uploads
#define TELEMETRY_RING          128     // bounded event buffer (drop-oldest)
#define TELEMETRY_BATCH         32

// ---- LEDs ------------------------------------------------------------------------
#define LED_DEFAULT_BRIGHTNESS_PCT 40
#define LED_AFTERGLOW_MS        10000
